// Copies the libraries the Web Playground provides (React 18 UMD builds,
// Vue's ESM browser build with its template compiler) into
// public/playground/vendor/, so the sandboxed runner loads them
// SAME-ORIGIN (no CDN; works offline). Git-ignored, regenerated by
// predev/prebuild.
import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "public", "playground", "vendor");
const FILES = [
  ["react/umd/react.production.min.js", "react.production.min.js"],
  ["react-dom/umd/react-dom.production.min.js", "react-dom.production.min.js"],
  ["vue/dist/vue.esm-browser.prod.js", "vue.esm-browser.prod.js"],
];
mkdirSync(out, { recursive: true });
let n = 0;
for (const [from, to] of FILES) {
  const src = join(root, "node_modules", from);
  if (!existsSync(src)) {
    console.warn(`copy-playground-vendor: missing ${from}`);
    continue;
  }
  copyFileSync(src, join(out, to));
  n++;
}
console.log(`copy-playground-vendor: ${n} files → public/playground/vendor/`);
